"""Process RpaChallengeInputFormsProcess: one transaction per spreadsheet row.

“Preparação” runs once before the rows, “Preenchimento por registro” once per row, “Conclusão” once after the rows.
A row with problems found by the spreadsheet reader is rejected before any action (``TABULAR_ROW_INVALID``).
"""

from __future__ import annotations

import json
from collections.abc import Mapping
from dataclasses import dataclass
from pathlib import Path

from nekkora_rpa import ProcessResult, RpaProcess, Runtime, TransactionItem
from nekkora_rpa.errors import BusinessRuleRejected
from nekkora_rpa.tabular import PROBLEMS_KEY

from automation.pages import ConclusionPage, PreparationPage, RecordFillingPage

START_URL = "https://rpachallenge.com/"


@dataclass(frozen=True, repr=False)
class InputRow:
    """One spreadsheet row: the columns the form uses (headers read in ``from_item``; the values are never logged)."""

    first_name: str
    last_name: str
    company_name: str
    role_in_company: str
    address: str
    email: str
    phone_number: str

    @classmethod
    def from_item(cls, item: TransactionItem) -> InputRow:
        """Reads the row of ``item``; a row with problems found by the spreadsheet reader is rejected before any
        action.
        """
        if item.data.get(PROBLEMS_KEY):
            raise BusinessRuleRejected("TABULAR_ROW_INVALID")
        return cls(
            first_name=_cell(item.data, "First Name"),
            last_name=_cell(item.data, "Last Name"),
            company_name=_cell(item.data, "Company Name"),
            role_in_company=_cell(item.data, "Role in Company"),
            address=_cell(item.data, "Address"),
            email=_cell(item.data, "Email"),
            phone_number=_cell(item.data, "Phone Number"),
        )


def _cell(data: Mapping[str, object], header: str) -> str:
    """Text of the column ``header`` (the spreadsheet reader already rejected rows with empty or missing cells)."""
    value = data.get(header)
    if not isinstance(value, str):
        raise TypeError(f"column {header!r} without text")
    return value


class RpaChallengeInputFormsProcess(RpaProcess):
    """One transaction per spreadsheet row: “Preparação” → “Preenchimento por registro” → “Conclusão”."""

    name = "rpa_challenge_input_forms"
    requires_browser = True
    required_secrets = ()

    def __init__(self, output: Path) -> None:
        self.output = output
        self.input_file: Path | None = None
        self.input_sha256: str | None = None
        self.observations: dict[str, str] = {}

    def init(self, rt: Runtime) -> None:
        """Opens the start address and goes through “Preparação” once, before the rows."""
        rt.act.navigate(START_URL, step_id="process.open_start_page")
        download_folder = self.output / "entrada" / rt.ctx.execution_id
        download_folder.mkdir(parents=True, exist_ok=True)
        preparation = PreparationPage(rt.act)
        spreadsheet = preparation.download_spreadsheet(download_folder)
        self.input_file, self.input_sha256 = spreadsheet.path, spreadsheet.sha256
        preparation.click_start()

    def process(self, rt: Runtime, item: TransactionItem) -> ProcessResult:
        """Goes through “Preenchimento por registro” with one spreadsheet row."""
        row = InputRow.from_item(item)
        RecordFillingPage(rt.act).submit_record(
            first_name=row.first_name,
            last_name=row.last_name,
            company_name=row.company_name,
            role_in_company=row.role_in_company,
            address=row.address,
            email=row.email,
            phone_number=row.phone_number,
        )
        return ProcessResult({"enviado": True})

    def end(self, rt: Runtime) -> None:
        """Goes through “Conclusão” once, after the rows."""
        self.observations["conclusion.read_result"] = ConclusionPage(rt.act).read_result()

    def write_observations(self) -> None:
        """Writes ``observacoes.json`` in the run folder: the texts read from the page, by ``step_id``, and the
        SHA-256 of the downloaded spreadsheet (never input values).
        """
        document = {"entrada_sha256": self.input_sha256, "observacoes": self.observations}
        (self.output / "observacoes.json").write_text(
            json.dumps(document, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
